import os
import base64
import six

from taf.internal.robot_typecasts import time_to_seconds, to_boolean

from ..util import wrap_result


class OtherProceduresInterface(object):
    """the interface for other keywords"""

    def set_dac_word(self,
                     dac_word,
                     target_fsm=None,
                     timeout=60):
        """Set DAC word.

        :param integer dac_word: DAC word.
        :param string target_fsm: primary or secondary. /
        None means a default Admin API behavior.
        :param float timeout: Time to wait for positive procedure result.
        
        """
        dac_word = int(dac_word)
        timeout = time_to_seconds(timeout)
        assert target_fsm in (None, "primary", "secondary")

        parameters = {
            "dacWord": dac_word,
        }

        if target_fsm:
            parameters["targetFSM"] = target_fsm

        self._api_client.execute_procedure("setDacWord",
                                                parameters, timeout)

    def set_vendor_file(self, vendor_file, technology_type=None,
                        timeout=300):
        """Set vendor file.

        :param string vendor_file: xml file or path to xml file.
        :param string technology_type: either "fdd", "tdd" or None for new implementation of Admin
        :param float timeout: Time to wait for positive procedure result
        
        """
        timeout = time_to_seconds(timeout)
        str(vendor_file)

        if os.path.isfile(vendor_file):
            with open(vendor_file, 'r') as f:
                vendor_file = f.read()

        six_vendor_file = six.b(vendor_file)
        b64_vendor_file = base64.b64encode(six_vendor_file)
        parameters = {"inputFileContent": b64_vendor_file}

        if technology_type is not None:
            str(technology_type)
            parameters["technologyType"] = technology_type

        return self._api_client.execute_procedure("setVendorFile", parameters, timeout)

    def download_vendor_file(self, target_file_name, timeout=60):
        """download vendor file.

        :param string target_file_name: target vendor_file filename.
        :param float timeout: Time to wait for positive procedure result
        
        """

        str(target_file_name)
        self._api_client.execute_infomodel_request(
            "downloadVendorFile", {}, timeout, output_file_name=target_file_name)

    def get_dac_word(self, timeout=60):
        """Get DAC word.

        :param float timeout: Time to wait for positive procedure result.
        

        :rtype: integer
        :return: DAC word
        """
        timeout = time_to_seconds(timeout)

        dac_word = self._api_client.execute_infomodel_request(
            "getDacWord", {}, timeout)
        return int(dac_word)

