    def switch_power_fuse(self, action, dist_name, timeout=60):
        """Change power state for fuse in power module.

        :param string action: action to be applied to the fuse with distName. Possible actions: powerOn, powerOff
        :param string dist_name: distName of fuse to be powerOn/powerOff.
                                 Possible distnames: /MRBTS-1/RAT-1/BTS_L-1/EQM_L-1/CABINET_L-1/PWRMOD_L-X/CONNECTOR_L-Y
        :param float timeout: Time to wait for positive procedure result.
        
        """
        timeout = time_to_seconds(timeout)
        self._api_client.execute_procedure("switchFuse",
                                                {"action": action,
                                                    "distName": dist_name},
                                                timeout)

    def set_clock_state(self,
                        clock_name="SOUT_SFCLK_100Hz",
                        enabled_state=True,
                        target_fsm=None,
                        timeout=10):
        """Set clock state.

        :param string clock_name: the clock name.
               Possible clock names: SOUT_SFCLK_100Hz, SOUT_SFCLK_50Hz,
               SOUT_SFCLK_25Hz, SOUT_SFCLK_12.5Hz,
               SOUT_SFCLK_Sfn0, SOUT_10MHz
        :param bool enabled_state: enable or disable the clock
        :param string target_fsm: primary | secondary
        :param float timeout: Time to wait for positive procedure result.
        
        :rtype: dict
        :return: requestStatus
        """
        enabled_state = str(to_boolean(enabled_state)).lower()
        timeout = time_to_seconds(timeout)

        assert target_fsm in (None, "primary", "secondary")

        assert clock_name in ("SOUT_10MHz",
                              "SOUT_SFCLK_100Hz",
                              "SOUT_SFCLK_50Hz",
                              "SOUT_SFCLK_25Hz",
                              "SOUT_SFCLK_12.5Hz",
                              "SOUT_SFCLK_Sfn0")

        parameters = {
            "clockName": clock_name,
            "enabledState": enabled_state,
        }

        if target_fsm:
            parameters["targetFSM"] = target_fsm

        return self._api_client.execute_procedure("setClockState", parameters, timeout)

